package mrpapermoon.whisper.mesh.dbimport androidx.room.Daoimport androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.Query@Daointerface NetworkMessageDao {	@Insert(onConflict = OnConflictStrategy.REPLACE)	suspend fun insert(message: NetworkMessageEntity): Long	@Insert(onConflict = OnConflictStrategy.REPLACE)	suspend fun insertAll(messages: List<NetworkMessageEntity>)	@Query("SELECT * FROM ${NetworkMessageEntity.TABLE_NAME} WHERE whispererId IN (:ids)")	suspend fun getMessagesByWhispererId(ids: List<String>): List<NetworkMessageEntity>	@Query("SELECT * FROM ${NetworkMessageEntity.TABLE_NAME} ORDER BY timestamp DESC")	suspend fun getAllMessages(): List<NetworkMessageEntity>}